// example.c is the working C example of transit (D10). It uses the upstream
// tree-sitter runtime at the base commit and the SQL grammar of
// DerekStride/tree-sitter-sql, generated by the upstream tool at the same
// commit, and it does each thing that rline and usql need from a parser:
//
//  1. parse a statement and print its tree
//  2. highlight it with the highlight query of the grammar, with the query
//     predicates evaluated as the Rust binding evaluates them
//  3. edit the text one key at a time, parse again with the old tree, and
//     report the changed ranges
//  4. find the node at a cursor offset, its parent, and its field
//  5. parse statements that are not finished, and print the ERROR and
//     MISSING nodes
//  6. list the symbols that the parser can accept at the cursor, with the
//     lookahead iterator
//  7. limit a query to a byte range
//  8. time each step, as the C baseline for the benchmarks of the Go runtime
//
// build.sh builds and runs it. docs/API.md maps each call that it makes to the
// target Go API.

#define _POSIX_C_SOURCE 200809L

#include <regex.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <tree_sitter/api.h>

const TSLanguage *tree_sitter_sql(void);

// now returns a monotonic time in nanoseconds.
static uint64_t now(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000000000u + (uint64_t)ts.tv_nsec;
}

// micros formats a duration in microseconds.
static double micros(uint64_t ns) { return (double)ns / 1000.0; }

// read_file returns the content of a file, or NULL.
static char *read_file(const char *path, uint32_t *length) {
  FILE *f = fopen(path, "rb");
  if (!f) return NULL;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  char *buf = malloc((size_t)n + 1);
  if (fread(buf, 1, (size_t)n, f) != (size_t)n) {
    fclose(f);
    free(buf);
    return NULL;
  }
  buf[n] = '\0';
  fclose(f);
  *length = (uint32_t)n;
  return buf;
}

// section prints the heading of one step.
static void section(int n, const char *title) {
  printf("\n== %d. %s\n", n, title);
}

// print_tree prints the S-expression of a node.
static void print_tree(TSNode node) {
  char *s = ts_node_string(node);
  printf("%s\n", s);
  free(s);
}

// text_of copies the text of a node into buf, cut to size.
static const char *text_of(TSNode node, const char *src, char *buf, size_t size) {
  uint32_t start = ts_node_start_byte(node), end = ts_node_end_byte(node);
  size_t n = end - start;
  if (n >= size) n = size - 1;
  memcpy(buf, src + start, n);
  buf[n] = '\0';
  return buf;
}

// ---------------------------------------------------------------------------
// Query predicates, as lib/binding_rust/lib.rs evaluates them. The C runtime
// parses predicates and does not evaluate them (D27).
//
// This evaluates eq?, not-eq?, match?, not-match?, any-of? and not-any-of?,
// which filter matches. set!, is? and is-not? set properties and filter
// nothing, so they are skipped. match? uses a POSIX extended regular
// expression here, where the Rust binding uses the crate regex. The two agree
// on the patterns of this grammar.

// capture_text returns the text of the first capture with the given index.
static bool capture_text(const TSQueryMatch *m, uint32_t index, const char *src,
                         char *buf, size_t size) {
  for (uint16_t i = 0; i < m->capture_count; i++) {
    if (m->captures[i].index == index) {
      text_of(m->captures[i].node, src, buf, size);
      return true;
    }
  }
  return false;
}

// predicates_hold reports whether the text predicates of a match hold.
static bool predicates_hold(const TSQuery *q, const TSQueryMatch *m, const char *src) {
  uint32_t count;
  const TSQueryPredicateStep *steps = ts_query_predicates_for_pattern(q, m->pattern_index, &count);
  uint32_t i = 0;
  while (i < count) {
    // one predicate runs up to a Done step
    uint32_t end = i;
    while (end < count && steps[end].type != TSQueryPredicateStepTypeDone) end++;
    uint32_t len;
    const char *op = ts_query_string_value_for_id(q, steps[i].value_id, &len);
    char a[512], b[512];
    bool negate = strncmp(op, "not-", 4) == 0;
    const char *name = negate ? op + 4 : op;
    bool ok = true;
    if (strcmp(name, "eq?") == 0 && end - i == 3) {
      if (!capture_text(m, steps[i + 1].value_id, src, a, sizeof a)) goto next;
      if (steps[i + 2].type == TSQueryPredicateStepTypeCapture) {
        if (!capture_text(m, steps[i + 2].value_id, src, b, sizeof b)) goto next;
      } else {
        snprintf(b, sizeof b, "%s", ts_query_string_value_for_id(q, steps[i + 2].value_id, &len));
      }
      ok = strcmp(a, b) == 0;
    } else if (strcmp(name, "match?") == 0 && end - i == 3) {
      if (!capture_text(m, steps[i + 1].value_id, src, a, sizeof a)) goto next;
      const char *pattern = ts_query_string_value_for_id(q, steps[i + 2].value_id, &len);
      regex_t re;
      if (regcomp(&re, pattern, REG_EXTENDED | REG_NOSUB) != 0) {
        fprintf(stderr, "cannot compile the pattern %s\n", pattern);
        ok = false;
      } else {
        ok = regexec(&re, a, 0, NULL, 0) == 0;
        regfree(&re);
      }
    } else if (strcmp(name, "any-of?") == 0 && end - i >= 2) {
      if (!capture_text(m, steps[i + 1].value_id, src, a, sizeof a)) goto next;
      ok = false;
      for (uint32_t j = i + 2; j < end; j++) {
        if (strcmp(a, ts_query_string_value_for_id(q, steps[j].value_id, &len)) == 0) ok = true;
      }
    } else {
      goto next;
    }
    if (ok == negate) return false;
  next:
    i = end + 1;
  }
  return true;
}

// ---------------------------------------------------------------------------

// highlight runs the highlight query on a node, and prints each capture in the
// order of the text. It returns the number of captures that it printed.
static int highlight(const TSQuery *q, TSNode root, const char *src, bool print,
                     uint32_t start, uint32_t end) {
  TSQueryCursor *qc = ts_query_cursor_new();
  if (end > start) ts_query_cursor_set_byte_range(qc, start, end);
  ts_query_cursor_exec(qc, q, root);
  TSQueryMatch m;
  uint32_t ci;
  int n = 0;
  while (ts_query_cursor_next_capture(qc, &m, &ci)) {
    if (!predicates_hold(q, &m, src)) {
      ts_query_cursor_remove_match(qc, m.id);
      continue;
    }
    TSQueryCapture c = m.captures[ci];
    uint32_t len;
    const char *name = ts_query_capture_name_for_id(q, c.index, &len);
    n++;
    if (print) {
      char buf[64];
      TSPoint p = ts_node_start_point(c.node);
      printf("  %-20s %-16s %2u:%-3u [%u,%u) %s\n", name, ts_node_type(c.node), p.row, p.column,
             ts_node_start_byte(c.node), ts_node_end_byte(c.node), text_of(c.node, src, buf, sizeof buf));
    }
  }
  ts_query_cursor_delete(qc);
  return n;
}

// field_in_parent returns the name of the field that holds a node in its
// parent, or NULL.
static const char *field_in_parent(TSNode node) {
  TSNode parent = ts_node_parent(node);
  if (ts_node_is_null(parent)) return NULL;
  TSTreeCursor c = ts_tree_cursor_new(parent);
  const char *field = NULL;
  if (ts_tree_cursor_goto_first_child(&c)) {
    do {
      if (ts_node_eq(ts_tree_cursor_current_node(&c), node)) {
        field = ts_tree_cursor_current_field_name(&c);
        break;
      }
    } while (ts_tree_cursor_goto_next_sibling(&c));
  }
  ts_tree_cursor_delete(&c);
  return field;
}

// print_errors walks a tree and prints each ERROR and MISSING node.
static void print_errors(TSNode node, const char *src, int depth) {
  char buf[64];
  if (ts_node_is_error(node)) {
    printf("  %*sERROR [%u,%u) \"%s\"\n", depth * 2, "", ts_node_start_byte(node),
           ts_node_end_byte(node), text_of(node, src, buf, sizeof buf));
  } else if (ts_node_is_missing(node)) {
    printf("  %*sMISSING %s at %u\n", depth * 2, "", ts_node_type(node), ts_node_start_byte(node));
  }
  if (!ts_node_has_error(node)) return;
  for (uint32_t i = 0; i < ts_node_child_count(node); i++) {
    print_errors(ts_node_child(node, i), src, depth + 1);
  }
}

// print_lookahead lists the symbols that the parser can accept in a state.
static void print_lookahead(const TSLanguage *lang, TSStateId state) {
  TSLookaheadIterator *it = ts_lookahead_iterator_new(lang, state);
  if (!it) {
    printf("  no lookahead iterator for state %u\n", state);
    return;
  }
  int n = 0;
  printf("  state %u accepts:", state);
  while (ts_lookahead_iterator_next(it)) {
    TSSymbol sym = ts_lookahead_iterator_current_symbol(it);
    if (ts_language_symbol_type(lang, sym) == TSSymbolTypeAuxiliary) continue;
    if (n < 24) printf(" %s", ts_lookahead_iterator_current_symbol_name(it));
    n++;
  }
  printf("%s (%d symbols)\n", n > 24 ? " ..." : "", n);
  ts_lookahead_iterator_delete(it);
}

// state_before returns the parse state just before a node: the state of its
// parent when it is the first child, and otherwise the next state of the
// sibling before it.
//
// ts_node_next_parse_state is not enough for a token. A token keeps the state
// in which the parser lexed it, and the parser can reduce before it shifts
// the token. Then the last action of the token in that state is a reduce, and
// ts_language_next_state returns 0. For "SELECT id FROM u", the token FROM
// keeps a state whose action for FROM is reduce(identifier, 1).
static TSStateId state_before(TSNode node) {
  TSNode prev = ts_node_prev_sibling(node);
  if (!ts_node_is_null(prev)) return ts_node_next_parse_state(prev);
  TSNode parent = ts_node_parent(node);
  return ts_node_is_null(parent) ? 1 : ts_node_parse_state(parent);
}

// lookahead_at prints the symbols that can come next at a byte offset. It
// takes the last leaf that ends at or before the cursor, and the state that
// the parser enters after that leaf. It asks ts_node_next_parse_state first,
// and falls back to state_before when that returns 0. Neither is right in
// every case, and inside an error both return 0, the state of the recovery.
// That is why transit adds an API for the states before a recovery (D28).
static void lookahead_at(const TSLanguage *lang, TSTree *tree, const char *src, uint32_t cursor) {
  TSNode root = ts_tree_root_node(tree);
  uint32_t at = cursor > 0 ? cursor - 1 : 0;
  // step back over white space, which is not in the tree
  while (at > 0 && (src[at] == ' ' || src[at] == '\n')) at--;
  TSNode leaf = ts_node_descendant_for_byte_range(root, at, at);
  char buf[64];
  TSStateId before = state_before(leaf);
  TSStateId after = ts_language_next_state(lang, before, ts_node_grammar_symbol(leaf));
  printf("  cursor %u, leaf %s \"%s\", in an error %s\n", cursor, ts_node_type(leaf),
         text_of(leaf, src, buf, sizeof buf), ts_node_has_error(ts_node_parent(leaf)) ? "yes" : "no");
  printf("  ts_node_next_parse_state: stored state %u, next state %u\n", ts_node_parse_state(leaf),
         ts_node_next_parse_state(leaf));
  printf("  state_before: state %u, next state %u\n", before, after);
  TSStateId next = ts_node_next_parse_state(leaf);
  print_lookahead(lang, next != 0 ? next : after);
}

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "usage: %s <highlights.scm>\n", argv[0]);
    return 2;
  }
  const TSLanguage *lang = tree_sitter_sql();
  printf("language %s, ABI %u, %u symbols, %u fields, %u states\n", ts_language_name(lang),
         ts_language_abi_version(lang), ts_language_symbol_count(lang),
         ts_language_field_count(lang), ts_language_state_count(lang));

  TSParser *parser = ts_parser_new();
  ts_parser_set_language(parser, lang);

  // 1. Parse.
  section(1, "parse a statement of more than one line");
  const char *src = "SELECT id, name, 42, 1.5\nFROM users\nWHERE age > 21 AND name = 'bob';\n";
  uint64_t t0 = now();
  TSTree *tree = ts_parser_parse_string(parser, NULL, src, (uint32_t)strlen(src));
  uint64_t t_parse = now() - t0;
  print_tree(ts_tree_root_node(tree));
  printf("  first parse: %.1f us\n", micros(t_parse));

  // 2. Highlight with the query of the grammar.
  section(2, "highlight with queries/highlights.scm");
  uint32_t qlen;
  char *qsrc = read_file(argv[1], &qlen);
  if (!qsrc) {
    fprintf(stderr, "cannot read %s\n", argv[1]);
    return 1;
  }
  uint32_t error_offset;
  TSQueryError error_type;
  t0 = now();
  TSQuery *query = ts_query_new(lang, qsrc, qlen, &error_offset, &error_type);
  uint64_t t_query_new = now() - t0;
  if (!query) {
    fprintf(stderr, "query error %d at offset %u\n", error_type, error_offset);
    return 1;
  }
  printf("  %u patterns, %u captures, compiled in %.1f us\n", ts_query_pattern_count(query),
         ts_query_capture_count(query), micros(t_query_new));
  t0 = now();
  int caps = highlight(query, ts_tree_root_node(tree), src, true, 0, 0);
  uint64_t t_highlight = now() - t0;
  printf("  %d captures in %.1f us\n", caps, micros(t_highlight));

  // 3. Edit one key at a time, and parse again with the old tree.
  section(3, "type one key at a time, and parse again with the old tree");
  const char *typed = "SELECT u.id, u.name FROM users u WHERE u.age > 21";
  size_t typed_len = strlen(typed);
  char *buf = calloc(typed_len + 1, 1);
  TSTree *old = ts_parser_parse_string(parser, NULL, "", 0);
  uint64_t total = 0, worst = 0;
  for (size_t i = 0; i < typed_len; i++) {
    buf[i] = typed[i];
    TSInputEdit edit = {
        .start_byte = (uint32_t)i,
        .old_end_byte = (uint32_t)i,
        .new_end_byte = (uint32_t)i + 1,
        .start_point = {0, (uint32_t)i},
        .old_end_point = {0, (uint32_t)i},
        .new_end_point = {0, (uint32_t)i + 1},
    };
    t0 = now();
    ts_tree_edit(old, &edit);
    TSTree *next = ts_parser_parse_string(parser, old, buf, (uint32_t)i + 1);
    uint32_t nranges;
    TSRange *ranges = ts_tree_get_changed_ranges(old, next, &nranges);
    highlight(query, ts_tree_root_node(next), buf, false, 0, 0);
    uint64_t d = now() - t0;
    total += d;
    if (d > worst) worst = d;
    if (i + 1 == typed_len || typed[i] == ' ') {
      printf("  key %2zu %-12s %u changed range%s", i + 1, "", nranges, nranges == 1 ? "" : "s");
      for (uint32_t r = 0; r < nranges; r++) printf(" [%u,%u)", ranges[r].start_byte, ranges[r].end_byte);
      printf(", %.1f us\n", micros(d));
    }
    free(ranges);
    ts_tree_delete(old);
    old = next;
  }
  printf("  %zu keys: edit + parse + changed ranges + highlight, mean %.1f us, worst %.1f us\n",
         typed_len, micros(total / typed_len), micros(worst));
  print_tree(ts_tree_root_node(old));

  // 4. The node at a cursor, its parent and its field.
  section(4, "the node at a cursor offset, its parent and its field");
  uint32_t offsets[] = {8, 25, 44};
  for (size_t i = 0; i < sizeof offsets / sizeof offsets[0]; i++) {
    TSNode n = ts_node_descendant_for_byte_range(ts_tree_root_node(old), offsets[i], offsets[i]);
    TSNode named = ts_node_named_descendant_for_byte_range(ts_tree_root_node(old), offsets[i], offsets[i]);
    const char *field = field_in_parent(named);
    char t1[64];
    printf("  offset %2u: leaf %s \"%s\", named %s, parent %s, field %s\n", offsets[i], ts_node_type(n),
           text_of(n, typed, t1, sizeof t1), ts_node_type(named), ts_node_type(ts_node_parent(named)),
           field ? field : "(none)");
  }

  // 5. Statements that are not finished.
  section(5, "statements that are not finished");
  const char *unfinished[] = {"SELECT * FROM ", "SELECT id, FROM users", "SELECT id FROM users WHERE "};
  TSTree *partial[3];
  for (int i = 0; i < 3; i++) {
    const char *s = unfinished[i];
    partial[i] = ts_parser_parse_string(parser, NULL, s, (uint32_t)strlen(s));
    printf("  \"%s\"\n  ", s);
    print_tree(ts_tree_root_node(partial[i]));
    print_errors(ts_tree_root_node(partial[i]), s, 0);
  }

  // 6. The symbols that can come next at the cursor.
  section(6, "the symbols that can come next at the cursor");
  for (int i = 0; i < 3; i++) {
    const char *s = unfinished[i];
    printf("  \"%s\"\n", s);
    lookahead_at(lang, partial[i], s, (uint32_t)strlen(s));
  }
  const char *complete = "SELECT id FROM ";
  printf("  \"%s\" and one more key, 'u'\n", complete);
  TSTree *more = ts_parser_parse_string(parser, NULL, "SELECT id FROM u", 16);
  lookahead_at(lang, more, "SELECT id FROM u", 15);
  ts_tree_delete(more);

  // 7. A query limited to a byte range: the second row of step 1.
  section(7, "highlight only the second row");
  uint32_t row2 = (uint32_t)(strchr(src, '\n') - src) + 1;
  uint32_t row2_end = (uint32_t)(strchr(src + row2, '\n') - src);
  printf("  bytes [%u,%u)\n", row2, row2_end);
  highlight(query, ts_tree_root_node(tree), src, true, row2, row2_end);

  // 8. Timings.
  section(8, "timings of this run, the C baseline");
  printf("  first parse %.1f us, query compile %.1f us, highlight %.1f us\n", micros(t_parse),
         micros(t_query_new), micros(t_highlight));
  printf("  per key: mean %.1f us, worst %.1f us, over %zu keys\n", micros(total / typed_len),
         micros(worst), typed_len);

  for (int i = 0; i < 3; i++) ts_tree_delete(partial[i]);
  ts_tree_delete(old);
  ts_tree_delete(tree);
  ts_query_delete(query);
  ts_parser_delete(parser);
  free(buf);
  free(qsrc);
  return 0;
}
